1	"use client";
2	
3	import type { AuthPageConfig, Testimonial } from "@/hooks/useAuthPageConfig";
4	import { Star } from "lucide-react";
5	
6	// ── Avatar colors for the social proof stack ───────────────────────────
7	const AVATAR_COLORS = [
8	  "bg-indigo-500",
9	  "bg-violet-500",
10	  "bg-purple-400",
11	  "bg-violet-300",
12	  "bg-purple-600",
13	];
14	
15	// ── Subcomponents ──────────────────────────────────────────────────────
16	
17	function Logo() {
18	  return (
19	    <div className="flex items-center gap-2.5">
20	      <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
21	        R
22	      </div>
23	      <span className="text-xl font-bold tracking-tight text-white">
24	        Rankora
25	      </span>
26	    </div>
27	  );
28	}
29	
30	function AvatarStack({
31	  count,
32	  label,
33	}: {
34	  count: string;
35	  label: string;
36	}) {
37	  return (
38	    <div className="flex items-center">
39	      {AVATAR_COLORS.map((color, i) => (
40	        <div
41	          key={i}
42	          className={`flex h-9 w-9 items-center justify-center rounded-full border-2 border-white/20 text-[11px] font-semibold text-white ${color} ${i > 0 ? "-ml-2" : ""}`}
43	        >
44	          {["SC", "AK", "MR", "JP", "TL"][i]}
45	        </div>
46	      ))}
47	      <span className="ml-3 text-[13px] text-white/60">
48	        <strong className="text-white">{count}</strong> {label}
49	      </span>
50	    </div>
51	  );
52	}
53	
54	function TestimonialCard({ testimonial }: { testimonial: Testimonial }) {
55	  return (
56	    <div className="rounded-[14px] border border-white/[0.07] bg-white/[0.05] p-5 backdrop-blur-sm">
57	      {/* Stars */}
58	      <div className="mb-2 flex gap-0.5">
59	        {Array.from({ length: testimonial.rating }).map((_, i) => (
60	          <Star
61	            key={i}
62	            className="h-3.5 w-3.5 fill-amber-400 text-amber-400"
63	          />
64	        ))}
65	      </div>
66	
67	      {/* Quote */}
68	      <p className="mb-3.5 text-[14px] italic leading-relaxed text-white/75">
69	        &ldquo;{testimonial.quote}&rdquo;
70	      </p>
71	
72	      {/* Author */}
73	      <div className="flex items-center gap-2.5">
74	        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-indigo-500 to-violet-400 text-xs font-bold text-white">
75	          {testimonial.avatar_initials}
76	        </div>
77	        <div>
78	          <div className="text-[13px] font-medium text-white/85">
79	            {testimonial.name}
80	          </div>
81	          <div className="text-[11px] text-white/40">
82	            {testimonial.role}, {testimonial.company}
83	          </div>
84	        </div>
85	      </div>
86	    </div>
87	  );
88	}
89	
90	// ── Main Panel ─────────────────────────────────────────────────────────
91	
92	interface AuthLeftPanelProps {
93	  config: AuthPageConfig;
94	  variant: "signin" | "signup";
95	}
96	
97	export function AuthLeftPanel({ config, variant }: AuthLeftPanelProps) {
98	  if (variant === "signup") {
99	    return <SignupLeftPanel config={config} />;
100	  }
101	  return <SigninLeftPanel config={config} />;
