103	
104	function SigninLeftPanel({ config }: { config: AuthPageConfig }) {
105	  const firstTestimonial = config.testimonials[0];
106	
107	  return (
108	    <div className="relative flex w-full flex-col justify-between overflow-hidden bg-gradient-to-br from-[#1a1a2e] to-[#2d2b55] p-10 lg:p-12">
109	      {/* Floating glow effects */}
110	      <div className="pointer-events-none absolute -right-20 -top-[120px] h-80 w-80 rounded-full bg-[radial-gradient(circle,rgba(99,102,241,0.12)_0%,transparent_70%)] animate-auth-glow" />
111	      <div className="pointer-events-none absolute -bottom-[60px] -left-[60px] h-60 w-60 rounded-full bg-[radial-gradient(circle,rgba(129,140,248,0.08)_0%,transparent_70%)] animate-auth-glow-reverse" />
112	
113	      {/* Logo */}
114	      <div className="relative z-10">
115	        <Logo />
116	      </div>
117	
118	      {/* Hero text */}
119	      <div className="relative z-10">
120	        <h2 className="mb-3.5 whitespace-pre-line text-[30px] font-bold leading-tight text-white">
121	          {config.hero_headline}
122	        </h2>
