141	
142	function SignupLeftPanel({ config }: { config: AuthPageConfig }) {
143	  return (
144	    <div className="relative flex w-full flex-col justify-center overflow-hidden bg-gradient-to-br from-[#1a1a2e] to-[#2d2b55] p-10 lg:p-12">
145	      {/* Floating glow */}
146	      <div className="pointer-events-none absolute -right-[60px] -top-[100px] h-[280px] w-[280px] rounded-full bg-[radial-gradient(circle,rgba(99,102,241,0.12)_0%,transparent_70%)] animate-auth-glow" />
147	
148	      <div className="relative z-10">
149	        <Logo />
150	
151	        <h2 className="mb-6 mt-9 whitespace-pre-line text-[26px] font-bold leading-snug text-white">
152	          {config.signup_headline}
153	        </h2>
154	
155	        {/* Benefits */}
156	        <div className="space-y-4">
157	          {config.signup_benefits.map((benefit, i) => (
158	            <div key={i} className="flex items-start gap-3">
159	              <div className="mt-0.5 flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-indigo-500/20">
160	                <svg
161	                  className="h-3.5 w-3.5 text-indigo-300"
162	                  viewBox="0 0 24 24"
163	                  fill="none"
164	                  stroke="currentColor"
165	                  strokeWidth={3}
166	                >
167	                  <path d="m5 12 5 5L20 7" />
168	                </svg>
169	              </div>
170	              <p className="text-[14px] leading-relaxed text-white/70">
171	                <strong className="font-medium text-white">
172	                  {benefit.highlight}
173	                </strong>{" "}
174	                — {benefit.text}
175	              </p>
176	            </div>
177	          ))}
178	        </div>
179	
180	        {/* Social proof */}
181	        <div className="mt-8">
182	          <AvatarStack
183	            count={config.signup_social_proof_count}
184	            label={config.signup_social_proof_label}
185	          />
186	        </div>
187	      </div>
188	    </div>
189	  );
190	}
