1	"use client";
2	
3	import { useState } from "react";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Input } from "@/components/ui/input";
6	import { toast } from "sonner";
7	import { Loader2 } from "lucide-react";
8	import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
9	import { SocialAuthButtons } from "./SocialAuthButtons";
10	import { Divider } from "./Divider";
11	import { TrustBadges } from "./TrustBadges";
12	
13	interface SignInFormProps {
14	  config: AuthPageConfig;
15	  onSuccess?: () => void;
16	  onSwitchToSignUp: () => void;
17	  onForgotPassword: () => void;
18	}
19	
20	export function SignInForm({
21	  config,
22	  onSuccess,
23	  onSwitchToSignUp,
24	  onForgotPassword,
25	}: SignInFormProps) {
26	  const [email, setEmail] = useState("");
27	  const [password, setPassword] = useState("");
28	  const [loading, setLoading] = useState(false);
29	
30	  const handleSubmit = async (e: React.FormEvent) => {
31	    e.preventDefault();
32	    setLoading(true);
33	    try {
34	      const { error } = await supabase.auth.signInWithPassword({
35	        email,
36	        password,
37	      });
38	      if (error) {
39	        toast.error(error.message);
40	      } else {
41	        toast.success("Signed in successfully");
42	        onSuccess?.();
43	      }
44	    } catch {
45	      toast.error("An unexpected error occurred. Please try again.");
46	    } finally {
47	      setLoading(false);
48	    }
49	  };
50	
51	  return (
52	    <div className="flex w-full flex-col justify-center bg-background px-8 py-12 sm:px-12 lg:px-14">
53	      <div className="mx-auto w-full max-w-[400px]">
54	        {/* Mobile logo — visible only below md */}
55	        <div className="mb-8 flex items-center gap-2.5 md:hidden">
56	          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
57	            R
58	          </div>
59	          <span className="text-xl font-bold tracking-tight">Rankora</span>
60	        </div>
61	
62	        {/* Header */}
63	        <div className="mb-7">
64	          <h2 className="text-[26px] font-bold tracking-tight text-foreground">
65	            {config.signin_heading}
66	          </h2>
67	          <p className="mt-1.5 text-[14px] text-muted-foreground">
68	            {config.signin_subheading}
69	          </p>
70	        </div>
71	
72	        {/* SSO */}
73	        <SocialAuthButtons
74	          googleEnabled={config.google_auth_enabled}
75	          microsoftEnabled={config.microsoft_auth_enabled}
76	          mode="signin"
77	          disabled={loading}
78	        />
79	
80	        {(config.google_auth_enabled || config.microsoft_auth_enabled) && (
81	          <div className="my-5">
82	            <Divider />
83	          </div>
84	        )}
85	
86	        {/* Email / Password form */}
87	        <form onSubmit={handleSubmit} className="space-y-4">
88	          <div className="space-y-1.5">
89	            <label
90	              htmlFor="signin-email"
91	              className="text-[13px] font-medium text-foreground/80"
92	            >
93	              Email
94	            </label>
95	            <Input
96	              id="signin-email"
97	              type="email"
98	              value={email}
99	              onChange={(e) => setEmail(e.target.value)}
100	              placeholder="name@company.com"
101	              autoComplete="email"
102	              required
103	              className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
104	            />
105	          </div>
106	
107	          <div className="space-y-1.5">
108	            <label
109	              htmlFor="signin-password"
110	              className="text-[13px] font-medium text-foreground/80"
111	            >
112	              Password
113	            </label>
114	            <Input
115	              id="signin-password"
116	              type="password"
117	              value={password}
118	              onChange={(e) => setPassword(e.target.value)}
119	              placeholder="Enter your password"
120	              autoComplete="current-password"
121	              required
122	              className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
123	            />
124	          </div>
125	
126	          {/* Remember me + Forgot */}
127	          <div className="flex items-center justify-between">
128	            <label className="flex cursor-pointer items-center gap-2 text-[13px] text-muted-foreground">
129	              <input
130	                type="checkbox"
131	                defaultChecked
132	                className="h-4 w-4 rounded accent-indigo-500"
133	              />
134	              Remember me
135	            </label>
136	            <button
137	              type="button"
138	              onClick={onForgotPassword}
139	              className="text-[13px] font-medium text-indigo-500 hover:underline"
140	            >
141	              Forgot password?
142	            </button>
143	          </div>
144	
145	          {/* Submit */}
146	          <button
147	            type="submit"
148	            disabled={loading}
149	            className="relative mt-2 flex w-full items-center justify-center rounded-[10px] bg-[#1a1a2e] px-4 py-3.5 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-[#2d2b55] hover:shadow-lg active:translate-y-0 disabled:opacity-50 dark:bg-indigo-600 dark:hover:bg-indigo-500"
150	          >
151	            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
152	            Sign in
153	          </button>
154	        </form>
155	
156	        {/* Switch to signup */}
157	        <p className="mt-5 text-center text-[13px] text-muted-foreground">
158	          Don&apos;t have an account?{" "}
159	          <button
160	            type="button"
161	            onClick={onSwitchToSignUp}
162	            className="font-semibold text-indigo-500 hover:underline"
163	          >
164	            Start free trial &rarr;
165	          </button>
166	        </p>
167	
168	        {/* Trust badges */}
169	        <div className="mt-6">
170	          <TrustBadges badges={config.trust_badges} />
171	        </div>
172	      </div>
173	    </div>
174	  );
175	}
