1	"use client";
2	
3	import { useState } from "react";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Input } from "@/components/ui/input";
6	import { toast } from "sonner";
7	import { Loader2 } from "lucide-react";
8	import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
9	import { SocialAuthButtons } from "./SocialAuthButtons";
10	import { Divider } from "./Divider";
11	import { TrustBadges } from "./TrustBadges";
12	
13	interface SignUpFormProps {
14	  config: AuthPageConfig;
15	  onSuccess?: () => void;
16	  onSwitchToSignIn: () => void;
17	}
18	
19	type Step = 1 | 2 | 3;
20	
21	export function SignUpForm({
22	  config,
23	  onSuccess,
24	  onSwitchToSignIn,
25	}: SignUpFormProps) {
26	  const [step, setStep] = useState<Step>(1);
27	  const [email, setEmail] = useState("");
28	  const [fullName, setFullName] = useState("");
29	  const [password, setPassword] = useState("");
30	  const [confirmPassword, setConfirmPassword] = useState("");
31	  const [loading, setLoading] = useState(false);
32	
33	  const handleStep1 = (e: React.FormEvent) => {
34	    e.preventDefault();
35	    if (!email) return;
36	    setStep(2);
37	  };
38	
39	  const handleStep2 = (e: React.FormEvent) => {
40	    e.preventDefault();
41	    if (!fullName) return;
42	    setStep(3);
43	  };
44	
45	  const handleStep3 = async (e: React.FormEvent) => {
46	    e.preventDefault();
47	    if (password !== confirmPassword) {
48	      toast.error("Passwords do not match");
49	      return;
50	    }
51	    if (password.length < 6) {
52	      toast.error("Password must be at least 6 characters");
53	      return;
54	    }
55	
56	    setLoading(true);
57	    try {
58	      const { error } = await supabase.auth.signUp({
59	        email,
60	        password,
61	        options: {
62	          emailRedirectTo: window.location.origin,
63	          data: { full_name: fullName },
64	        },
65	      });
66	      if (error) {
67	        toast.error(error.message);
68	      } else {
69	        toast.success("Check your email to confirm your account!");
70	        onSuccess?.();
71	      }
72	    } catch {
73	      toast.error("An unexpected error occurred. Please try again.");
74	    } finally {
75	      setLoading(false);
76	    }
77	  };
78	
79	  const stepLabel = `Step ${step} of 3`;
80	
81	  return (
82	    <div className="flex w-full flex-col justify-center bg-background px-8 py-12 sm:px-12 lg:px-14">
83	      <div className="mx-auto w-full max-w-[400px]">
84	        {/* Mobile logo */}
85	        <div className="mb-8 flex items-center gap-2.5 md:hidden">
86	          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-indigo-500 to-indigo-400 text-sm font-extrabold text-white">
87	            R
88	          </div>
89	          <span className="text-xl font-bold tracking-tight">Rankora</span>
90	        </div>
91	
92	        {/* Step indicator */}
93	        <div className="mb-6 flex items-center gap-2">
94	          {([1, 2, 3] as const).map((s) => (
95	            <div
96	              key={s}
97	              className={`h-2 rounded-full transition-all duration-300 ${
98	                s === step
99	                  ? "w-6 bg-indigo-500"
100	                  : s < step
101	                    ? "w-2 bg-green-500"
102	                    : "w-2 bg-border"
103	              }`}
104	            />
105	          ))}
106	        </div>
107	
108	        {/* Header */}
109	        <div className="mb-7">
110	          <h2 className="text-[26px] font-bold tracking-tight text-foreground">
111	            {config.signup_heading}
112	          </h2>
113	          <p className="mt-1.5 text-[14px] text-muted-foreground">
114	            {stepLabel} — {stepSubheading(step)}
115	          </p>
116	        </div>
117	
118	        {/* Step 1: Email only */}
119	        {step === 1 && (
120	          <>
121	            <SocialAuthButtons
122	              googleEnabled={config.google_auth_enabled}
123	              microsoftEnabled={config.microsoft_auth_enabled}
124	              mode="signup"
125	              disabled={loading}
126	            />
127	
128	            {(config.google_auth_enabled ||
129	              config.microsoft_auth_enabled) && (
130	              <div className="my-5">
131	                <Divider />
132	              </div>
133	            )}
134	
135	            <form onSubmit={handleStep1} className="space-y-4">
136	              <div className="space-y-1.5">
137	                <label
138	                  htmlFor="signup-email"
139	                  className="text-[13px] font-medium text-foreground/80"
140	                >
141	                  Work email
142	                </label>
143	                <Input
144	                  id="signup-email"
145	                  type="email"
146	                  value={email}
147	                  onChange={(e) => setEmail(e.target.value)}
148	                  placeholder="name@company.com"
149	                  autoComplete="email"
150	                  autoFocus
151	                  required
152	                  className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
153	                />
154	              </div>
155	
156	              <button
157	                type="submit"
158	                className="flex w-full items-center justify-center rounded-[10px] bg-indigo-500 px-4 py-3.5 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-indigo-600 hover:shadow-lg active:translate-y-0"
159	              >
160	                Continue &rarr;
161	              </button>
162	            </form>
163	          </>
164	        )}
165	
166	        {/* Step 2: Full name */}
167	        {step === 2 && (
168	          <form onSubmit={handleStep2} className="space-y-4">
169	            <div className="space-y-1.5">
170	              <label
171	                htmlFor="signup-name"
172	                className="text-[13px] font-medium text-foreground/80"
173	              >
174	                Full name
175	              </label>
176	              <Input
177	                id="signup-name"
178	                type="text"
179	                value={fullName}
180	                onChange={(e) => setFullName(e.target.value)}
181	                placeholder="Jane Smith"
182	                autoComplete="name"
183	                autoFocus
184	                required
185	                className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
186	              />
187	            </div>
188	
189	            <div className="flex gap-3">
190	              <button
191	                type="button"
192	                onClick={() => setStep(1)}
193	                className="flex-1 rounded-[10px] border border-border px-4 py-3 text-[14px] font-medium text-foreground transition-colors hover:bg-muted"
194	              >
195	                Back
196	              </button>
197	              <button
198	                type="submit"
199	                className="flex flex-[2] items-center justify-center rounded-[10px] bg-indigo-500 px-4 py-3 text-[14px] font-semibold text-white transition-all hover:-translate-y-px hover:bg-indigo-600 hover:shadow-lg active:translate-y-0"
200	              >
201	                Continue &rarr;
202	              </button>
203	            </div>
204	          </form>
205	        )}
206	
207	        {/* Step 3: Password */}
208	        {step === 3 && (
209	          <form onSubmit={handleStep3} className="space-y-4">
210	            <div className="space-y-1.5">
211	              <label
212	                htmlFor="signup-password"
213	                className="text-[13px] font-medium text-foreground/80"
214	              >
215	                Password
216	              </label>
217	              <Input
218	                id="signup-password"
219	                type="password"
220	                value={password}
221	                onChange={(e) => setPassword(e.target.value)}
222	                placeholder="Min 6 characters"
223	                autoComplete="new-password"
224	                autoFocus
225	                required
226	                minLength={6}
227	                className="h-[46px] rounded-[10px] border-border bg-background px-3.5 text-[14px] placeholder:text-muted-foreground/40 focus-visible:border-indigo-500 focus-visible:ring-indigo-500/10"
228	              />
229	              <p className="text-xs text-muted-foreground">
230	                At least 6 characters required
231	              </p>
